<?php
namespace Api;require_once __DIR__.'/../core/Guard.php';ml_guard_shield(__FILE__);require_once __DIR__.'/../core/User.php';use Core\Config;use Core\Json;use Core\CacheStore;use Core\Http;use Core\User;use Adapters\Tmdb;class TmdbProxy{public static function handle($a){$b=trim($a,'/');$c=explode('/',$b);array_shift($c);$d=(isset($c[0])?$c[0]:'');self::guardKey();self::guardRate();$e=new Tmdb();$f=(int)Config::sub('cache','ttl_days',7);if(in_array($d,['movie','tv','person'],true)){$g=(isset($c[1])?$c[1]:'');if(!is_numeric($g)){Json::error(400,'invalid id');}CacheStore::bumpApiCall('tmdb',$d,$g);$h=CacheStore::getRaw('tmdb',$d,$g);if($h!==null&&CacheStore::isFresh('tmdb',$d,$g)){Json::send($h);}$i=$e->fetchRaw($d,$g);if(empty($i['id'])){Json::error(404,'not found');}CacheStore::put('tmdb',$d,$g,$e->normalize($i,$d),$i,$f);Json::send($i);}if($d==='search'){$j=(isset($c[1])?$c[1]:'multi');$k=self::query();$l=(isset($k['query'])?$k['query']:'');$m=(int)((isset($k['page'])?$k['page']:1));if($l===''){Json::error(400,'query required');}if(!in_array($j,['movie','tv','person','multi'],true)){Json::error(400,'bad search type');}$n='proxy_search_'.$j.'_'.md5($l).'_'.$m;$o=CacheStore::shortGet($n);if(is_array($o)){Json::send($o);}$i=$e->searchRaw($j,$l,$m);foreach((isset($i['results'])?$i['results']:[])as $p){$q=(isset($p['media_type'])?$p['media_type']:$j);if(in_array($q,['movie','tv','person'],true)){CacheStore::put('tmdb',$q,(string)$p['id'],$e->normalize($p,$q),$p,$f);}}if(isset($i['success'])&&$i['success']===false){Json::send($i);}CacheStore::shortSet($n,$i,300);Json::send($i);}if($d==='trending'){$r=(isset($c[1])?$c[1]:'all');$s=(isset($c[2])?$c[2]:'week');if(!in_array($r,['all','movie','tv','person'],true)){$r='all';}if(!in_array($s,['day','week'],true)){$s='week';}$n='proxy_trending_'.$r.'_'.$s;$o=CacheStore::shortGet($n);if(is_array($o)){Json::send($o);}$i=$e->trendingRaw($r,$s);CacheStore::shortSet($n,$i,600);Json::send($i);}if($d==='genre'){$t=(isset($c[1])?$c[1]:'movie');if(!in_array($t,['movie','tv'],true)){Json::error(400,'bad genre type');}$n='proxy_genre_'.$t;$o=CacheStore::shortGet($n);if(is_array($o)){Json::send($o);}$u=Http::get($e->url("/genre/{$t}/list"))['data'];CacheStore::shortSet($n,$u,3600);Json::send($u);}if($d==='configuration'){$n='proxy_configuration';$o=CacheStore::shortGet($n);if(is_array($o)){Json::send($o);}$u=Http::get($e->url('/configuration'))['data'];CacheStore::shortSet($n,$u,3600);Json::send($u);}Json::error(404,'endpoint not found');}private static function guardKey(){if(!Config::sub('proxy','require_key',false)){return;}$a=trim((string)Config::sub('proxy','proxy_key',''));if($a===''){$a=(string)Config::sub('tmdb','api_key','');}$b='';$c=self::query();if(isset($c['api_key'])&&is_string($c['api_key'])){$b=trim($c['api_key']);}if($b===''&&isset($_SERVER['HTTP_X_API_KEY'])){$b=trim((string)$_SERVER['HTTP_X_API_KEY']);}if($a===''||$b===''||!hash_equals($a,$b)){Json::error(401,'proxy key required');}}private static function guardRate(){$a=(int)Config::sub('proxy','rate_per_min',60);if($a<=0){return;}$b=(string)User::ip();$c='proxy_rl_'.md5($b.'_'.(int)floor(time()/60));$d=CacheStore::shortGet($c);$e=is_int($d)?$d:0;if($e>=$a){Json::error(429,'请求过于频繁，请一分钟后再试');}CacheStore::shortSet($c,$e+1,130);}private static function query(){$a=$_SERVER['REQUEST_METHOD'];if($a==='GET'){$b=parse_url($_SERVER['REQUEST_URI'],PHP_URL_QUERY);parse_str(($b===null?'':$b),$c);return $c;}$d=json_decode((string)file_get_contents('php://input'),true);return is_array($d)?$d:[];}}